    # Step 1: Count frequency of each number
    freq = {}
    for num in nums:
        if num not in freq:
            freq[num] = 0
        freq[num] += 1

    # Step 2: The answer is the maximum frequency of any value
    max_freq = 0
    for count in freq.values():
        if count > max_freq:
            max_freq = count

    # Step 3: At least max_freq groups are needed
    return max_freq
